ighlight{margin:0 0 24px;font:inherit;font-size:var(--wutm-popup-highlight-size);font-weight:800;line-height:1.05;color:var(--wutm-popup-accent)}.wutm-popup-designed-banner .wutm-popup-designed-highlight{color:#fff}.wutm-popup-designed-button{display:inline-block;padding:12px 24px;border-radius:7px;background:var(--wutm-popup-accent);color:#fff!important;text-decoration:none;font-weight:700}.wutm-popup-designed-banner .wutm-popup-designed-button{background:#fff;color:#101828!important}@media(max-width:600px){.wutm-popup-designed{padding:48px 24px}}@media(prefers-reduced-motion:reduce){#wutm-popup-overlay{backdrop-filter:none}}</style><div id="wutm-popup-overlay" aria-hidden="true"><div id="wutm-popup-box" role="dialog" aria-modal="true" aria-label="網站活動"><button type="button" id="wutm-popup-close" aria-label="關閉">×</button><div id="wutm-popup-slider"></div><div id="wutm-popup-dots" class="wutm-popup-dots"></div></div></div>
<script>(function(){document.addEventListener('DOMContentLoaded',function(){var key='wutm-homepage-popup-seen',o=document.getElementById('wutm-popup-overlay'),s=document.getElementById('wutm-popup-slider'),d=document.getElementById('wutm-popup-dots'),c=0,t;function hide(){o.classList.remove('active');o.setAttribute('aria-hidden','true');if(t)clearTimeout(t)}function addText(parent,tag,className,value){if(!value)return;var el=document.createElement(tag);el.className=className;el.textContent=value;parent.appendChild(el)}function go(i){var es=s.querySelectorAll('.wutm-popup-slide-front'),ds=d.querySelectorAll('.wutm-popup-dot');if(!es.length)return;es[c].classList.remove('active');if(ds[c])ds[c].classList.remove('active');c=(i+es.length)%es.length;es[c].classList.add('active');if(ds[c])ds[c].classList.add('active')}function renderTemplate(v){var e=document.createElement('div');v=v||{};e.className='wutm-popup-designed wutm-popup-designed-'+(v.template||'spotlight');e.style.setProperty('--wutm-popup-accent',v.accent||'#2271b1');e.style.setProperty('--wutm-popup-title-size',(v.title_size||34)+'px');e.style.setProperty('--wutm-popup-highlight-size',(v.highlight_size||52)+'px');addText(e,'h2','wutm-popup-designed-title',v.title);addText(e,'p','wutm-popup-designed-subtitle',v.subtitle);addText(e,'p','wutm-popup-designed-highlight',v.highlight);if(v.button_text){var b=document.createElement(v.button_link?'a':'span');b.className='wutm-popup-designed-button';b.textContent=v.button_text;if(v.button_link)b.href=v.button_link;e.appendChild(b)}s.appendChild(e)}function renderSlides(x){var a=x.slides||[];if(x.mode==='random'&&a.length)a=[a[Math.floor(Math.random()*a.length)]];a.forEach(function(v,i){var e=document.createElement('div'),w=document.createElement(v.link?'a':'div'),im=document.createElement('img');e.className='wutm-popup-slide-front'+(!i?' active':'');if(v.link){w.href=v.link;w.target=v.link_target||'_self';if(w.target==='_blank')w.rel='noopener'}im.src=v.image_url;im.al